    return null;
  }
}
export function setMode(m: Mode | null) {
  if (m) sessionStorage.setItem(KEY, JSON.stringify(m));
  else sessionStorage.removeItem(KEY);
}

export function parentToken(): string | undefined {
  const m = getMode();
  return m?.kind === "parent" ? m.token : undefined;
}

